      ctx.globalAlpha = al; ctx.beginPath(); ctx.arc(nx, ny, r, 0, 7); ctx.fillStyle = s.fill || '#fff'; ctx.fill();
      ctx.strokeStyle = s.ring || NAVY; ctx.lineWidth = 7 * sc; ctx.stroke();
