      const sec = u0 * 16, kR = Math.min(NL, Math.floor(sec / 0.55)), kL = sec <= 7 ? Math.min(NB, Math.floor(sec / 0.55)) : Math.round(lerp(Math.floor(7 / 0.55), NB, ease((sec - 7) / 8.4)));
